import{_ as s,o as t,a as e,b as l}from"./app.BAU4IqPF.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"Memory矢量计算","link":"/api/SIMD-API/c_api/vector_compute/memory_vector_compute"},{"text":"asc_set_vector_mask","link":"/api/SIMD-API/c_api/vector_compute/asc_set_vector_mask"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/vector_compute/asc_set_vector_mask.md","filePath":"api/SIMD-API/c_api/vector_compute/asc_set_vector_mask.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"流水类型","slug":"流水类型","link":"#流水类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1785895910000}'),c={name:"api/SIMD-API/c_api/vector_compute/asc_set_vector_mask.md"};function i(n,a,r,_,p,o){return t(),e("div",null,[...a[0]||(a[0]=[l(`<div><article class="markdown-body"><h1>asc_set_vector_mask</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：不支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>某些矢量计算接口需要提前设置Mask，提示哪些数据需要参与计算。 该API用于设置Mask，使用前需要先调用<a href="asc_set_mask_count.html">asc_set_mask_count</a>和<a href="asc_set_mask_norm.html">asc_set_mask_norm</a>设置Mask模式。在不同的模式下Mask的含义如下：</p><ul><li>Normal模式用于高维切分计算类API。该模式下，Mask参数用来控制单次迭代内参与计算的元素。可以按位控制哪些元素参与计算：bit位的值为1表示参与计算，0表示不参与。分为mask1(高位Mask)和mask0（低位Mask）。参数取值范围和操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同。当操作数为16位时，mask0，mask1∈[0, 2^64-1]，并且不同时为0；当操作数为32位时，mask1为0，mask0∈(0, 2^64-1]；当操作数为64位时，mask1为0，mask0∈(0, 2^32-1]。</li><li>Counter模式用于前n个数据计算类API。该模式下，Mask参数用于控制整个计算过程中参与计算的元素个数。前n个数据计算类接口中已经实现了Normal模式和Counter模式的转换，用户不需要进行自行设置。</li></ul><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_set_vector_mask</span><span class="p">(</span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">mask1</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">mask0</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>mask1</td><td>输入</td><td>Normal模式：高位mask值。<br>Counter模式：需要置0，本入参不生效。</td></tr><tr><td>mask0</td><td>输入</td><td>Normal模式：低位mask值。<br>Counter模式：整个矢量计算过程中，参与计算的元素个数。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="流水类型">流水类型<a class="header-anchor" href="#流水类型">​</a></h2><p>PIPE_S</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><p>需先调用<a href="asc_set_mask_count.html">asc_set_mask_count</a>或<a href="asc_set_mask_norm.html">asc_set_mask_norm</a>设置Mask模式。</p><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>请参考<a href="asc_set_mask_count.html#%E8%B0%83%E7%94%A8%E7%A4%BA%E4%BE%8B">asc_set_mask_count</a>或<a href="asc_set_mask_norm.html#%E8%B0%83%E7%94%A8%E7%A4%BA%E4%BE%8B">asc_set_mask_norm</a>。</p></article></div>`,1)])])}const m=s(c,[["render",i]]);export{h as __pageData,m as default};
